// TH14 v1.00b Stage 3 道中波 MainSub06c (st03.ecl.txt:750-775)
// 依赖：GirlC01 (236-256)、GirlC01_at (258-293)。
// 源编队：右3/左3/右3，每只间隔60；第1/3组 enmCreateM(子镜像1, x=224)，
// 第2组 enmCreate(镜像0, x=-224)，y=160、hp=260、score=1000、item=1。

const TIME_LIMIT: int = 3000;
const OPENING_BUFFER: int = 120;

// TH14 源 type8 = 米弹；词表 TH14_RICE=480（type 0-23 同号），色号4原样。
const TH14_RICE: int = 480;
const BULLET_COLOR: int = 4;

// 源 EX 程序 (GirlC01_at:269-271,276)：
//   [0] ANIM a=1 · [1] SPEEDUP async=1 · [2] WAIT a=60 · [3] ACCEL a=60 r=0.025 s=keep-angle
// ANIM/SPEEDUP 属出生表现，按共用口径省略；ANIM a=1 的 4*初速退位移与 etDist 合成到 sh_dist。
// WAIT 只停 EX 游标；ACCEL 方向按进入时当前弹角取固定向量，弹角恒90°(下)，故为 (0,+0.025)，
// 持续60帧后清两轴。
xformdef BULLET_EX {
    wait(60);
    @60 set_gravity(0fx, 0.025fx);
    set_gravity(0fx, 0fx);
}

// 源 GirlC01_at (258-293)：%A=π/2；%F0 在本闭包内从未写入，
// 故 %A += %F0 恒保持 90°。每发 etCount(0,1,1) 一颗、etSpeed(0.5,1.0) M=1 取 0.5、
// etAim(0,3) 固定方向环。
async sub shoot() {
    var a: angle = 90deg;
    wait(60);                        // 源 wait(60) 后才 etNew/配置
    sh_reset(0);
    sh_sprite(0, TH14_RICE, BULLET_COLOR);   // etSprite(0,8,4)
    sh_ring(0, 1);                   // etAim(0,3)：固定方向整周环
    sh_aim(0, 0);
    sh_count(0, 1, 1);
    sh_speed(0, 0.5fx, 0fx);
    // 源 etDist(0,16) 沿弹角 + ANIM a=1 退位移 4*0.5=2px → 净 14px
    sh_dist(0, 14fx);
    sh_xform(0, BULLET_EX);

    // 源难度掩码 !E 40 / !N 20 / !H 15 / !LO 10（本卡 ranks=[0,3]）
    var interval: int = 10;
    var rank: int = global(GVAR_RANK);
    if rank == RANK_EASY { interval = 40; }
    if rank == RANK_NORMAL { interval = 20; }
    if rank == RANK_HARD { interval = 15; }

    // 源 $B=50 的 do-while：50发，每发后 wait(interval)，末发后也有一次 wait。
    var i: int = 0;
    while i < 50 {
        sh_angle(0, a, 0deg);        // etAngle(0,%A,0)：%A 恒90°
        sh_fire(0);
        wait(interval);
        i = i + 1;
    }
}

// 源 GirlC01 (236-256)
async sub girl(mirror: int) {
    set_invuln(65535);               // 训练外壳：真实敌同样无敌
    // anmSelect/anmSetMain/anmSetSprite、dropMain/dropExtra：表现/掉落省略
    set_hurtbox(12fx);               // setHurtbox(24,24)：普通圆取第一值×0.5
    set_hitbox(8fx);                 // setHitbox(16,16)：16×0.5
    // moveVel(-π/4,1.5) → moveVelTime(80, mode1=EASE_QUAD_IN, 0, 1.5)
    // enmCreateM 子镜像1：源角度按x镜像 θ→180°−θ（镜像不作用于发弹角）。
    var start_a: angle = -45deg;
    var end_a: angle = 0deg;
    if mirror != 0 {
        start_a = 225deg;
        end_a = 180deg;
    }
    move_vel(0, start_a, 1.5fx, EASE_LINEAR);
    move_vel(80, end_a, 1.5fx, EASE_QUAD_IN);
    spawn shoot();                   // @GirlC01_at() async
    loop { wait(1000); }             // wait(120) 后进入 wait(1000) 无限循环
}

// 源 MainSub06c (750-775)：三组各3只、间隔60；组间不额外等待。
async sub pattern() {
    wait(OPENING_BUFFER);
    var group: int = 0;
    while group < 3 {
        var i: int = 0;
        while i < 3 {
            if group == 1 {
                _ = spawn_enemy(-224fx, 160fx, 260, 0, 1000, 0, girl(0));
            } else {
                _ = spawn_enemy(224fx, 160fx, 260, 0, 1000, 0, girl(1));
            }
            wait(60);
            i = i + 1;
        }
        group = group + 1;
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
